package com.family.tracker.parent
import android.app.*; import android.content.Context; import android.content.Intent; import android.os.IBinder; import android.widget.Toast; import fi.iki.elonen.NanoHTTPD; import java.io.File
class PhotoHttpServerService:Service(){private var srv:PhotoServer?=null
inner class PhotoServer(port:Int):NanoHTTPD(port){override fun serve(s:IHTTPSession):Response{if(s.method==Method.POST&&s.uri=="/upload"){try{val f=s.parseBody(mapOf());val p=f["photo"]?:return newFixedLengthResponse(Response.Status.BAD_REQUEST,"text/plain","No file");val file=File(p);val d=file.readBytes();val i=Intent("PHOTO_RECEIVED").setPackage(packageName);i.putExtra("photo_data",d);sendBroadcast(i);file.delete();return newFixedLengthResponse(Response.Status.OK,"text/plain","OK")}catch(e:Exception){return newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain",e.message)}}return newFixedLengthResponse(Response.Status.NOT_FOUND,"text/plain","Not found")}}
override fun onCreate(){super.onCreate();srv=PhotoServer(8904);try{srv?.start()}catch(e:Exception){Toast.makeText(this,"Port 8904 occupé",Toast.LENGTH_SHORT).show()};val c=NotificationChannel("photo_server","Serveur Photo",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager::class.java).createNotificationChannel(c);startForeground(2,Notification.Builder(this,"photo_server").setContentTitle("Serveur photo actif").setSmallIcon(android.R.drawable.ic_dialog_info).build())}override fun onBind(i:Intent?):IBinder?=null;override fun onDestroy(){srv?.stop();super.onDestroy()}}
